        "UV_OFFLINE": "1",
        "UV_PYTHON_DOWNLOADS": "never",
        "GIT_OPTIONAL_LOCKS": "0",
        "PIP_DISABLE_PIP_VERSION_CHECK": "1",
    }
    cache = _cache_dir()
    if cache is not None:
        env["UV_CACHE_DIR"] = str(cache)
    if extra:
        env.update(extra)
    return env


